class OrderAdded(TypedDict):
  """Result of placing a new order."""

  descr: NotRequired[OrderDescription]
  txid: NotRequired[list[str]]
  """Transaction ID(s) for the order -- present only once the order actually reaches the matching engine, i.e. absent when `validate` was set."""


validate_add_order = validator(OrderAdded)


class AddOrder(RpcEndpoint):
  """`spot.trading.add_order`."""

  async def add_order(
    self,
    order: AddOrderMarket
    | AddOrderLimit
    | AddOrderIceberg
    | AddOrderStopLoss
    | AddOrderTakeProfit
    | AddOrderStopLossLimit
    | AddOrderTakeProfitLimit
    | AddOrderTrailingStop
    | AddOrderTrailingStopLimit
    | AddOrderSettlePosition,
    *,
    validate: bool | None = None,
  ) -> OrderAdded:
    """Place a new order. See `AssetPairs` for tradable pairs, their price/quantity precisions, order minimums, and available leverage.

    **API Key Permissions Required:** `Orders and trades - Create & modify orders`

    Args:
      order: Parameters for placing a new Spot order. The valid combination of `price`/`price2`/`displayvol`/`trigger` depends on `ordertype` -- see each variant below.
      validate: Override this call's response validation; falls back to the client-level default when omitted.

    References:
      - [Official docs](https://docs.kraken.com/api-reference/trading/add-order)
    """
    data = dict(order)
    if (deadline := order.get('deadline')) is not None:
      data['deadline'] = timestamp_iso.dump(deadline)
    return await self.authed_request(
      '/0/private/AddOrder', data, validator=validate_add_order, validate=validate
    )
